--
-- TOC entry 261 (class 1259 OID 41662)
-- Name: docs_ipc; Type: VIEW; Schema: fin; Owner: postgres
--

CREATE VIEW fin.docs_ipc AS
 SELECT purcases.pcs_id AS docid,
    purcases.pcs_type AS doctype,
    purcases.pcs_date AS rdate,
    purcases.pcs_title AS title,
    purcases.pcs_effhed_id AS effhed_id,
    purcases.pcs_effunt_id AS effunt_id,
    purcases.pcs_hed_id AS hed_id,
    purcases.pcs_unt_id AS unt_id,
    purcases.pcs_sudohed AS sudohed,
    purcases.pcs_midprice AS amount1,
    purcases.pcs_midtax AS tax1,
    purcases.pcs_price AS amount2,
    purcases.pcs_transtype AS transtype
   FROM pur.purcases
  WHERE ((purcases.pcs_status)::text = ANY ((ARRAY['Under Scrutiny'::character varying, 'Under Revision'::character varying, 'Under Approval'::character varying])::text[]))
UNION ALL
 SELECT salorders.sor_id AS docid,
    salorders.sor_type AS doctype,
    salorders.sor_releasedtg AS rdate,
    ('Salary for '::text || (salorders.sor_empnamecomp)::text) AS title,
    salorders.sor_effhed_id AS effhed_id,
    salorders.sor_effunt_id AS effunt_id,
    salorders.sor_hed_id AS hed_id,
    salorders.sor_unt_id AS unt_id,
    salorders.sor_sudohed AS sudohed,
    salorders.sor_salary AS amount1,
    0 AS tax1,
    salorders.sor_salary AS amount2,
    salorders.sor_transtype AS transtype
   FROM (hr.salreqs
     JOIN fin.salorders ON ((salreqs.srq_id = salorders.sor_srq_id)))
  WHERE (((salorders.sor_status)::text = 'Draft'::text) AND ((salreqs.srq_status)::text = 'In Process'::text));


ALTER VIEW fin.docs_ipc OWNER TO postgres;

